import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';const lock=JSON.parse(fs.readFileSync('SOURCE_LOCK.json','utf8'));for(const f of lock.files){const b=fs.readFileSync(f.path);assert.equal(b.length,f.bytes,f.path+' size');assert.equal(crypto.createHash('sha256').update(b).digest('hex'),f.sha256,f.path+' hash');}console.log('Source lock PASS: '+lock.files.length+' exact files, '+lock.version);
